-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.assessment_settings (
  user_id uuid default auth.uid() not null,
  deck_id text not null,
  include_extras boolean default false not null,
  new_per_day smallint,
  updated_at timestamp with time zone default now() not null,
  exam_date date,
  final_review_days smallint default 3 not null,
  exam_date_set_at timestamp with time zone,
  constraint assessment_settings_pkey PRIMARY KEY (user_id, deck_id),
  constraint assessment_settings_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint assessment_settings_deck_id_check CHECK ((deck_id ~ '^[0-9]{1,20}$'::text)),
  constraint assessment_settings_exam_date_check CHECK (((exam_date >= '2000-01-01'::date) AND (exam_date <= '2100-12-31'::date))),
  constraint assessment_settings_final_review_days_check CHECK ((final_review_days = ANY (ARRAY[1, 3, 7]))),
  constraint assessment_settings_new_per_day_check CHECK (((new_per_day >= 0) AND (new_per_day <= 9999)))
);

CREATE TRIGGER quota_rows AFTER INSERT ON public.assessment_settings FOR EACH ROW EXECUTE FUNCTION public.quota_rows('1000');

alter table public.assessment_settings enable row level security;

create policy "own assessment settings" on public.assessment_settings
  as permissive
  for all
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant delete, insert, select, update on table public.assessment_settings to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.assessment_settings to service_role;
